   109	package hotel.reservations;
   110	
   111	import hotel.rooms.Room;
   112	import java.math.BigDecimal;
   113	import java.math.RoundingMode;
   114	import java.time.LocalDate;
   115	import java.time.Month;
   116	
   117	/**
   118	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   119	 * high-season nights; the rate plan may fix the price instead and may give a discount on it. Money is rounded to cents
   120	 * (half-even) at every step.
   121	 */
   122	public final class PriceCalculator {
   123	
   124	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   125	
   126	    public Price calculate(Room room, NewReservation request) {
   127	        int nights = 0;
   128	        BigDecimal nightsTotal = cents(BigDecimal.ZERO);
   129	        for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
   130	            nightsTotal = nightsTotal.add(nightPrice(room, night));
   131	            nights++;
   132	        }
   133	        RatePlan ratePlan = request.ratePlan();
   134	        BigDecimal subtotal = ratePlan.subtotal(room, nightsTotal);
   135	        BigDecimal discount = ratePlan.discount(subtotal, request);
   136	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   137	    }
   138	
   139	    BigDecimal nightPrice(Room room, LocalDate night) {
   140	        BigDecimal nightlyRate = room.nightlyRate();
   141	        if (isHighSeason(night)) {
   142	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   143	        }
   144	        return cents(nightlyRate);
   145	    }
   146	
   147	    /** High season: from December 15 to the end of February, and the whole of July. */
   148	    static boolean isHighSeason(LocalDate date) {
   149	        Month month = date.getMonth();
   150	        return month == Month.JANUARY
   151	                || month == Month.FEBRUARY
   152	                || month == Month.JULY
   153	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   154	    }
   155	
   156	    static BigDecimal cents(BigDecimal value) {
   157	        return value.setScale(2, RoundingMode.HALF_EVEN);
   158	    }
   159	}

