  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	
  8	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
  9	public final class ReservationService {
 10	
 11	    static final String HOTEL_NAME = "Pousada Maré Alta";
 12	
 13	    private final Rooms rooms;
 14	    private final ReservationStore store;
 15	    private final PriceCalculator priceCalculator;
 16	    private final EmailSender emailSender;
 17	
 18	    public ReservationService(
 19	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 20	        this.rooms = rooms;
 21	        this.store = store;
 22	        this.priceCalculator = priceCalculator;
 23	        this.emailSender = emailSender;
 24	    }
 25	
 26	    public synchronized Reservation create(NewReservation request) {
 27	        if (!request.checkOut().isAfter(request.checkIn())) {
 28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 29	        }
 30	        if (request.guests() < 1) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 32	        }
 33	        Room room = rooms.find(request.roomNumber())
 34	                .orElseThrow(() -> new HotelException(
 35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 36	        if (request.guests() > room.capacity()) {
 37	            throw new HotelException(
 38	                    ErrorCode.CAPACITY_EXCEEDED,
 39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 40	        }
 41	        request.ratePlan().checkAllowed(request);
 42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 43	            throw new HotelException(
 44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 45	        }
 46	        Price price = priceCalculator.calculate(room, request);
 47	        return store.add(request, price);
 48	    }
 49	
 50	    public Reservation find(long reservationId) {
 51	        return store.find(reservationId)
 52	                .orElseThrow(() -> new HotelException(
 53	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 54	    }
 55	
 56	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 57	    public synchronized Reservation confirm(long reservationId) {
 58	        Reservation reservation = find(reservationId);
 59	        if (reservation.status() != ReservationStatus.PENDING) {
 60	            throw notAllowed(reservation, "confirm");
 61	        }
 62	        reservation.confirmPayment();
 63	        store.update(reservation);
 64	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 65	        emailSender.send(
 66	                reservation.guest().email(),
 67	                "Reserva confirmada - " + HOTEL_NAME,
 68	                confirmationEmailBody(reservation, receipt));
 69	        return reservation;
 70	    }
 71	
 72	    /**
 73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 74	     * reservation was never paid, so nothing comes back).
 75	     */
 76	    public synchronized Reservation cancel(long reservationId) {
 77	        Reservation reservation = find(reservationId);
 78	        if (reservation.status() != ReservationStatus.PENDING
 79	                && reservation.status() != ReservationStatus.CONFIRMED) {
 80	            throw notAllowed(reservation, "cancel");
 81	        }
 82	        reservation.cancel(reservation.ratePlan().refund(reservation.amountPaid()));
 83	        store.update(reservation);
 84	        return reservation;
 85	    }
 86	
 87	    public synchronized Reservation checkIn(long reservationId) {
 88	        Reservation reservation = find(reservationId);
 89	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 90	            throw notAllowed(reservation, "check in");
 91	        }
 92	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 93	        store.update(reservation);
 94	        return reservation;
 95	    }
 96	
 97	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
 98	    public synchronized ReservationReceipt checkOut(long reservationId) {
 99	        Reservation reservation = find(reservationId);
100	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
101	            throw notAllowed(reservation, "check out");
102	        }
103	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
104	        store.update(reservation);
105	        return new ReservationReceipt(reservation, roomOf(reservation));
106	    }
107	
108	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
109	    public ReservationReceipt receiptCopy(long reservationId) {
110	        Reservation reservation = find(reservationId);
111	        if (!reservation.isPaid()) {
112	            throw notAllowed(reservation, "issue a receipt for");
113	        }
114	        return new ReservationReceipt(reservation, roomOf(reservation));
115	    }
116	
117	    private Room roomOf(Reservation reservation) {
118	        return rooms.find(reservation.roomNumber()).orElseThrow();
119	    }
120	
121	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
122	        return "Olá, " + reservation.guest().name() + "!\n\n"
123	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
124	                + receipt.text() + "\n"
125	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
126	                + "Até breve!\n";
127	    }
128	
129	    private static HotelException notAllowed(Reservation reservation, String operation) {
